149: ## Testing Camel Routes
150: 
151: ```java
152: @QuarkusTest
153: @DisplayName("Business Rules Camel Route Tests")
154: class BusinessRulesRouteTest {
155: 
156:   @Inject
157:   CamelContext camelContext;
158: 
159:   @Inject
160:   ProducerTemplate producerTemplate;
161: 
162:   @InjectMock
163:   EventService eventService;
164: 
165:   @InjectMock
166:   DocumentValidator documentValidator;
167: 
168:   private BusinessRulesPayload testPayload;
169: 
170:   @BeforeEach
171:   void setUp() {
172:     // ARRANGE - Test data
173:     testPayload = new BusinessRulesPayload();
174:     testPayload.setDocumentId(1L);
175:     testPayload.setFlowProfile(FlowProfile.BASIC);
176:   }
177: 
178:   @Nested
179:   @DisplayName("Tests for business-rules-publisher route")
180:   class BusinessRulesPublisher {
181: 
182:     @Test
183:     @DisplayName("Should successfully publish message to RabbitMQ")
184:     void givenValidPayload_whenPublish_thenMessageSentToQueue() throws Exception {
185:       // ARRANGE
186:       MockEndpoint mockRabbitMQ = camelContext.getEndpoint("mock:rabbitmq", MockEndpoint.class);
187:       mockRabbitMQ.expectedMessageCount(1);
188: 
189:       // Replace real endpoint with mock for testing
190:       camelContext.getRouteController().stopRoute("business-rules-publisher");
191:       AdviceWith.adviceWith(camelContext, "business-rules-publisher", advice -> {
192:         advice.replaceFromWith("direct:business-rules-publisher");
193:         advice.weaveByToString(".*spring-rabbitmq.*").replace().to("mock:rabbitmq");
194:       });
195:       camelContext.getRouteController().startRoute("business-rules-publisher");
196: 
197:       // ACT
198:       producerTemplate.sendBody("direct:business-rules-publisher", testPayload);
199: 
200:       // ASSERT — body is a JSON String after .marshal().json(JsonLibrary.Jackson)
201:       mockRabbitMQ.assertIsSatisfied(5000);
202: 
203:       assertThat(mockRabbitMQ.getExchanges()).hasSize(1);
204:       String body = mockRabbitMQ.getExchanges().get(0).getIn().getBody(String.class);
205:       assertThat(body).contains("\"documentId\":1");
206:     }
207: 
208:     @Test
209:     @DisplayName("Should handle marshalling to JSON")
210:     void givenPayload_whenPublish_thenMarshalledToJson() throws Exception {
211:       // ARRANGE
212:       MockEndpoint mockMarshal = new MockEndpoint("mock:marshal");
213:       camelContext.addEndpoint("mock:marshal", mockMarshal);
214:       mockMarshal.expectedMessageCount(1);
215: 
216:       camelContext.getRouteController().stopRoute("business-rules-publisher");
217:       AdviceWith.adviceWith(camelContext, "business-rules-publisher", advice -> {
218:         advice.weaveAddLast().to("mock:marshal");
219:       });
220:       camelContext.getRouteController().startRoute("business-rules-publisher");
221: 
222:       // ACT
223:       producerTemplate.sendBody("direct:business-rules-publisher", testPayload);
224: 
225:       // ASSERT
226:       mockMarshal.assertIsSatisfied(5000);
227: 
228:       String body = mockMarshal.getExchanges().get(0).getIn().getBody(String.class);
229:       assertThat(body).contains("\"documentId\":1");
230:       assertThat(body).contains("\"flowProfile\":\"BASIC\"");
231:     }
232:   }
233: 
234:   @Nested
235:   @DisplayName("Tests for document-processing route")
236:   class DocumentProcessing {
237: 
238:     @Test
239:     @DisplayName("Should route invoice to correct processor")
240:     void givenInvoiceType_whenProcess_thenRoutesToInvoiceProcessor() throws Exception {
241:       // ARRANGE
242:       MockEndpoint mockInvoice = camelContext.getEndpoint("mock:invoice", MockEndpoint.class);
243:       mockInvoice.expectedMessageCount(1);
244: 
245:       camelContext.getRouteController().stopRoute("document-processing");
246:       AdviceWith.adviceWith(camelContext, "document-processing", advice -> {
247:         advice.weaveByToString(".*direct:process-invoice.*").replace().to("mock:invoice");
248:       });
249:       camelContext.getRouteController().startRoute("document-processing");
250: 
251:       // ACT
252:       producerTemplate.sendBodyAndHeader("direct:process-document",
253:           testPayload, "documentType", "INVOICE");
254: 
255:       // ASSERT
256:       mockInvoice.assertIsSatisfied(5000);
257:     }
258: 
259:     @Test
260:     @DisplayName("Should handle validation errors gracefully")
261:     void givenValidationError_whenProcess_thenRoutesToErrorHandler() throws Exception {
262:       // ARRANGE
263:       MockEndpoint mockError = camelContext.getEndpoint("mock:error", MockEndpoint.class);
264:       mockError.expectedMessageCount(1);
265: 
266:       camelContext.getRouteController().stopRoute("document-processing");
267:       AdviceWith.adviceWith(camelContext, "document-processing", advice -> {
268:         advice.weaveByToString(".*direct:validation-error-handler.*")
269:             .replace().to("mock:error");
270:       });
271:       camelContext.getRouteController().startRoute("document-processing");
272: 
273:       // Mock validator bean to throw exception
274:       when(documentValidator.validate(any())).thenThrow(new ValidationException("Invalid document"));
275: 
276:       // ACT
277:       producerTemplate.sendBody("direct:process-document", testPayload);
278: 
279:       // ASSERT
280:       mockError.assertIsSatisfied(5000);
281: 
282:       Exception exception = mockError.getExchanges().get(0).getException();
283:       assertThat(exception).isInstanceOf(ValidationException.class);
284:       assertThat(exception.getMessage()).contains("Invalid document");
285:     }
286:   }
287: }
