379:     @ParameterizedTest
380:     @DisplayName("Should reject invalid error messages")
381:     @ValueSource(strings = {"", " "})
382:     void givenBlankErrorMessage_whenCreateErrorEvent_thenThrowsException(String blankMessage) {
383:       // ACT & ASSERT
384:       IllegalArgumentException exception = assertThrows(
385:           IllegalArgumentException.class,
386:           () -> eventService.createErrorEvent(testPayload, "ERROR", blankMessage)
