395: ## Testing CompletableFuture
396: 
397: ```java
398: @ExtendWith(MockitoExtension.class)
399: @DisplayName("FileStorageService Unit Tests")
400: class FileStorageServiceTest {
401: 
402:   @Mock
403:   private S3Client s3Client;
404: 
405:   @Mock
406:   private ExecutorService executorService;
407: 
408:   @InjectMocks
409:   private FileStorageService fileStorageService;
410: 
411:   private InputStream testInputStream;
412:   private LogContext testLogContext;
413: 
414:   @BeforeEach
415:   void setUp() {
416:     // ARRANGE
417:     testInputStream = new ByteArrayInputStream("test content".getBytes());
418:     testLogContext = new LogContext();
419:     testLogContext.put("traceId", "trace-123");
420:   }
421: 
422:   @Nested
423:   @DisplayName("Tests for uploadOriginalFile")
424:   class UploadOriginalFile {
425: 
426:     @Test
427:     @DisplayName("Should successfully upload file and return document info")
428:     void givenValidFile_whenUpload_thenReturnsDocumentInfo() throws Exception {
429:       // ARRANGE
430:       doAnswer(invocation -> {
431:         ((Runnable) invocation.getArgument(0)).run();
432:         return null;
433:       }).when(executorService).execute(any(Runnable.class));
434: 
435:       when(s3Client.putObject(any(PutObjectRequest.class), any(RequestBody.class)))
436:           .thenReturn(PutObjectResponse.builder().build());
437: 
438:       // ACT
439:       CompletableFuture<StoredDocumentInfo> future =
440:           fileStorageService.uploadOriginalFile(testInputStream, 1024L,
441:               testLogContext, InvoiceFormat.UBL);
442: 
443:       StoredDocumentInfo result = future.join();
444: 
445:       // ASSERT
446:       assertThat(result).isNotNull();
447:       assertThat(result.getPath()).isNotBlank();
448:       assertThat(result.getSize()).isEqualTo(1024L);
449:       assertThat(result.getUploadedAt()).isNotNull();
450: 
451:       verify(s3Client).putObject(any(PutObjectRequest.class), any(RequestBody.class));
452:     }
453: 
454:     @Test
455:     @DisplayName("Should handle S3 upload failure")
456:     void givenS3Failure_whenUpload_thenCompletableFutureFails() {
457:       // ARRANGE — run synchronously so exception propagates through the future
458:       doAnswer(invocation -> {
459:         ((Runnable) invocation.getArgument(0)).run();
460:         return null;
461:       }).when(executorService).execute(any(Runnable.class));
462: 
463:       when(s3Client.putObject(any(PutObjectRequest.class), any(RequestBody.class)))
464:           .thenThrow(new StorageException("S3 unavailable"));
465: 
466:       // ACT
467:       CompletableFuture<StoredDocumentInfo> future =
468:           fileStorageService.uploadOriginalFile(testInputStream, 1024L,
469:               testLogContext, InvoiceFormat.UBL);
470: 
471:       // ASSERT
472:       assertThatThrownBy(() -> future.join())
473:           .isInstanceOf(CompletionException.class)
474:           .hasCauseInstanceOf(StorageException.class)
475:           .hasMessageContaining("S3 unavailable");
476:     }
477: 
478:     @Test
479:     @DisplayName("Should propagate LogContext to async operation")
480:     void givenLogContext_whenUpload_thenContextPropagated() throws Exception {
481:       // ARRANGE
482:       AtomicReference<LogContext> capturedContext = new AtomicReference<>();
483: 
484:       doAnswer(invocation -> {
485:         capturedContext.set(CustomLog.getCurrentContext());
486:         ((Runnable) invocation.getArgument(0)).run();
487:         return null;
488:       }).when(executorService).execute(any(Runnable.class));
489: 
490:       // ACT
491:       fileStorageService.uploadOriginalFile(testInputStream, 1024L,
492:           testLogContext, InvoiceFormat.UBL).join();
493: 
494:       // ASSERT
495:       assertThat(capturedContext.get()).isNotNull();
496:       assertThat(capturedContext.get().get("traceId")).isEqualTo("trace-123");
497:     }
498:   }
499: }
500: ```
