521:       when(documentService.list(0, 20)).thenReturn(documents);
522: 
523:       // ACT & ASSERT
524:       given()
525:           .when().get("/api/documents")
526:           .then()
527:           .statusCode(200)
528:           .body("$.size()", is(1))
529:           .body("[0].referenceNumber", equalTo("DOC-001"));
530:     }
531:   }
