533:   @Nested
534:   @DisplayName("Tests for POST /api/documents")
535:   class CreateDocument {
536: 
537:     @Test
538:     @DisplayName("Should create document and return 201")
539:     void givenValidRequest_whenCreate_thenReturns201() {
540:       // ARRANGE
541:       Document document = createDocument(1L, "DOC-001");
542:       when(documentService.create(any())).thenReturn(document);
543: 
544:       // ACT & ASSERT
545:       given()
546:           .contentType(ContentType.JSON)
547:           .body("""
