563:     @DisplayName("Should return 400 for invalid input")
564:     void givenInvalidRequest_whenCreate_thenReturns400() {
565:       // ACT & ASSERT
566:       given()
567:           .contentType(ContentType.JSON)
568:           .body("""
569:               {
570:                 "referenceNumber": "",
571:                 "description": "Test"
572:               }
573:               """)
